diff --git a/src/todos.ts b/src/todos.ts
index f4d7666..bd996a4 100644
--- a/src/todos.ts
+++ b/src/todos.ts
@@ -24,7 +24,8 @@ export class TodoStore {

   remove(id: number): boolean {
     const index = this.todos.findIndex((t) => t.id === id);
+    if (index === -1) return false;
     this.todos.splice(index, 1);
-    return index !== -1;
+    return true;
   }
 }
diff --git a/test/todos.test.ts b/test/todos.test.ts
index 244c7b7..3ae09ad 100644
--- a/test/todos.test.ts
+++ b/test/todos.test.ts
@@ -21,6 +21,16 @@ test("toggle flips done", () => {
 test("remove deletes the todo", () => {
   const store = new TodoStore();
   const { id } = store.add("Call mom");
+  const other = store.add("Pay rent");
   assert.equal(store.remove(id), true);
-  assert.deepEqual(store.list(), []);
+  assert.deepEqual(store.list(), [other]);
+});
+
+test("remove of an unknown id returns false and keeps the list", () => {
+  const store = new TodoStore();
+  store.add("Call mom");
+  store.add("Pay rent");
+  const before = store.list();
+  assert.equal(store.remove(999), false);
+  assert.deepEqual(store.list(), before);
 });
